def merge_ranges(ranges):
    # Filter out empty ranges (where start >= end)
    valid = [r for r in ranges if r[0] < r[1]]
    # Sort ranges by start point
    valid.sort(key=lambda x: x[0])
    merged = []
    for r in valid:
        if not merged:
            merged.append(r)
        else:
            last = merged[-1]
            # If current range overlaps or touches the last merged range, merge them
            if r[0] <= last[1]:
                merged[-1] = (last[0], max(last[1], r[1]))
            else:
                merged.append(r)
    return merged

import heapq
def topological(edges, nodes):
    all_nodes = set(nodes)
    for u, v in edges:
        all_nodes.add(u)
        all_nodes.add(v)
    adj = {node: [] for node in all_nodes}
    indeg = {node: 0 for node in all_nodes}
    seen = set()
    for u, v in edges:
        if (u, v) in seen:
            continue
        seen.add((u, v))
        adj[u].append(v)
        indeg[v] += 1
    heap = [node for node in all_nodes if indeg[node] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                heapq.heappush(heap, neighbor)
    if len(result) != len(all_nodes):
        raise ValueError()
    return result

from collections import OrderedDict
def lru(capacity, operations):
    if capacity == 0:
        results = []
        for op in operations:
            if op[0] == "get":
                results.append(-1)
            # puts ignored
        return results
    cache = OrderedDict()
    results = []
    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache.pop(key)
            cache[key] = value
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

def flatten(value):
    if isinstance(value, list) or isinstance(value, tuple):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

import heapq
def shortest(graph, start, end):
    if start == end:
        return 0
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if node == end:
            return d
        if node not in graph:
            continue
        for neighbor, weight in graph.get(node, []):
            new_d = d + weight
            if neighbor not in dist or new_d < dist[neighbor]:
                dist[neighbor] = new_d
                heapq.heappush(heap, (new_d, neighbor))
    return None

from collections import deque
def window_max(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(values):
        return []
    dq = deque()
    result = []
    for i, val in enumerate(values):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and values[dq[-1]] < val:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(values[dq[0]])
    return result

def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    key_events = {}
    result = []
    for t, key in events:
        if key not in key_events:
            key_events[key] = []
        timestamps = key_events[key]
        # Remove timestamps outside the window (including t-window)
        while timestamps and timestamps[0] <= t - window:
            timestamps.pop(0)
        if len(timestamps) < limit:
            timestamps.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

