def stable_unique(values):
    result = []
    for v in values:
        for r in result:
            if r == v:
                break
        else:
            result.append(v)
    return result

def parse_duration(text):
    if not text:
        raise ValueError()
    total = 0
    i = 0
    n = len(text)
    while i < n:
        if not text[i].isdigit():
            raise ValueError()
        num = 0
        while i < n and text[i].isdigit():
            num = num * 10 + ord(text[i]) - ord('0')
            i += 1
        if i >= n:
            raise ValueError()
        unit = text[i]
        i += 1
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num * 1
        else:
            raise ValueError()
    return total

def paginate(items, after, limit):
    if limit <= 0:
        raise ValueError()
    # Sort items by id
    sorted_items = sorted(items, key=lambda x: x['id'])
    # Filter by after
    if after is not None:
        sorted_items = [item for item in sorted_items if item['id'] > after]
    # Take page up to limit
    page = sorted_items[:limit]
    # Determine next_cursor
    next_cursor = None
    if page:
        if len(sorted_items) > len(page):
            next_cursor = page[-1]['id']
        else:
            next_cursor = None
    else:
        next_cursor = None
    return (page, next_cursor)

def retry_delays(attempts, initial, cap):
    if attempts < 0 or initial < 0 or cap < 0:
        raise ValueError("Negative arguments")
    delays = []
    for i in range(attempts):
        delay = initial * (2 ** i)
        if delay > cap:
            delay = cap
        delays.append(delay)
    return delays

