from io import StringIO
def csv_records(text):
    if not text:
        return []
    reader = csv.reader(StringIO(text))
    try:
        headers = next(reader)
    except StopIteration:
        return []
    if len(headers) != len(set(headers)):
        raise ValueError("Duplicate headers")
    records = []
    for row in reader:
        if len(row) != len(headers):
            raise ValueError("Different number of fields")
        records.append(dict(zip(headers, row)))
    return records

def version_sort(versions):
    def key(v):
        parts = [int(x) for x in v.split('.')]
        # strip trailing zero segments
        while parts and parts[-1] == 0:
            parts.pop()
        return tuple(parts)
    return sorted(versions, key=key)

def memo_cycle(definitions, name):
    visited = set()
    def helper(n):
        if n in visited:
            raise ValueError
        if n not in definitions:
            raise ValueError
        val = definitions[n]
        if isinstance(val, int):
            return val
        elif isinstance(val, list):
            visited.add(n)
            total = 0
            for dep in val:
                total += helper(dep)
            visited.remove(n)
            return total
        else:
            raise ValueError
    return helper(name)
